package in.recallradar;
import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.http.MediaType; import org.springframework.test.context.ActiveProfiles; import org.springframework.test.web.servlet.MockMvc; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc @ActiveProfiles("test") class AuthIntegrationTest { @Autowired MockMvc mvc; @Test void registrationLoginAndProtectedDashboardWork() throws Exception {String register="{\"fullName\":\"Test Manager\",\"organizationName\":\"Test Kitchens\",\"email\":\"manager@example.com\",\"password\":\"very-secure-pass\",\"setupCode\":\"test-setup\"}";mvc.perform(post("/api/auth/register").contentType(MediaType.APPLICATION_JSON).content(register)).andExpect(status().isCreated()).andExpect(jsonPath("$.accessToken").exists());var login=mvc.perform(post("/api/auth/login").contentType(MediaType.APPLICATION_JSON).content("{\"email\":\"manager@example.com\",\"password\":\"very-secure-pass\"}")).andExpect(status().isOk()).andReturn().getResponse().getContentAsString();String token=login.replaceAll(".*\\\"accessToken\\\":\\\"([^\\\"]+).*","$1");mvc.perform(get("/api/dashboard").header("Authorization","Bearer "+token)).andExpect(status().isOk()).andExpect(jsonPath("$.phase").value(1));mvc.perform(get("/api/organizations").header("Authorization","Bearer "+token)).andExpect(status().isOk()).andExpect(jsonPath("$[0].name").value("Test Kitchens"));} @Test void organizationAdminCanAddTenantScopedMasterData() throws Exception {String register="{\"fullName\":\"Second Manager\",\"organizationName\":\"South Kitchens\",\"email\":\"second@example.com\",\"password\":\"very-secure-pass\",\"setupCode\":\"test-setup\"}";var response=mvc.perform(post("/api/auth/register").contentType(MediaType.APPLICATION_JSON).content(register)).andExpect(status().isCreated()).andReturn().getResponse().getContentAsString();String token=response.replaceAll(".*\\\"accessToken\\\":\\\"([^\\\"]+).*","$1");var orgs=mvc.perform(get("/api/organizations").header("Authorization","Bearer "+token)).andExpect(status().isOk()).andReturn().getResponse().getContentAsString();String org=orgs.replaceAll(".*\\\"id\\\":\\\"([^\\\"]+).*","$1");mvc.perform(post("/api/master-data/locations").header("Authorization","Bearer "+token).header("X-Organization-Id",org).contentType(MediaType.APPLICATION_JSON).content("{\"name\":\"Pune Outlet\",\"type\":\"OUTLET\",\"address\":\"Pune\"}")).andExpect(status().isCreated()).andExpect(jsonPath("$.name").value("Pune Outlet"));mvc.perform(get("/api/master-data/locations").header("Authorization","Bearer "+token).header("X-Organization-Id","00000000-0000-0000-0000-000000000000")).andExpect(status().isForbidden());} @Test void dashboardRejectsAnonymousRequest() throws Exception {mvc.perform(get("/api/dashboard")).andExpect(status().isForbidden());}}
